import { MISSIONS, PARTS, DEFAULT_DESIGNS, CATEGORIES, SOURCES } from './data.js';
import { calculate, getMission, getPart, normalizeDesign, createFlight, flightChoices, advanceFlight, summarize, remainingDv, restoreFlight, FLIGHT_STAGES } from './engine.js';
import { mountGlobe } from './globe.js';

const KEY='hail-mary:v1';
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const paths={
  grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  rocket:'M12 15 9 12c0-5 5-8 11-8 0 6-3 11-8 11Z M9 8H5l-3 5 7-1 M16 15v4l-5 3 1-7 M6 16l-3 5 5-3 M15 8h.01',
  arrow:'M4 12h16 M14 6l6 6-6 6', check:'m5 12 4 4L19 6', close:'m6 6 12 12 M6 18 18 6',
  moon:'M20 13A8 8 0 0 1 11 4a8 8 0 1 0 9 9Z',
  radio:'M8 8a6 6 0 0 0 0 8 M16 8a6 6 0 0 1 0 8 M4 4a12 12 0 0 0 0 16 M20 4a12 12 0 0 1 0 16 M12 11v10 M11 10h2v2h-2Z',
  book:'M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1Zm0 0v15',
  archive:'M3 4h18v4H3z M5 8v13h14V8 M9 12h6',
  globe:'M21 12A9 9 0 1 1 3 12a9 9 0 1 1 18 0 M3 12h18 M12 3c-5 5-5 13 0 18 5-5 5-13 0-18',
  scan:'M8 3H3v5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M8 8h8v8H8z',
  sun:'M16 12a4 4 0 1 1-8 0 4 4 0 1 1 8 0 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',
  flame:'M12 2c2 6 6 6 6 12a6 6 0 0 1-12 0c0-3 2-6 3-7 0 3 2 3 3 4 2-3 0-6 0-9Z',
  battery:'M2 6h17v12H2z M22 10v4 M6 9v6 M10 9v6 M14 9v6',
  sliders:'M4 3v18 M12 3v18 M20 3v18 M1 8h6 M9 16h6 M17 7h6',
  download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',
  share:'M9 8 16 4 M9 16l7 4 M9 12a3 3 0 1 1-6 0 3 3 0 1 1 6 0 M21 3a3 3 0 1 1-6 0 3 3 0 1 1 6 0 M21 21a3 3 0 1 1-6 0 3 3 0 1 1 6 0',
  info:'M12 17v-5 M12 8h.01 M21 12a9 9 0 1 1-18 0 9 9 0 1 1 18 0',
  clock:'M12 7v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 1 1 18 0',
  flag:'M5 21V3h14l-3 5 3 5H5',
  chart:'M4 3v18h17 M8 16v-4 M13 16V7 M18 16v-7',
  spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',
  volume:'M4 9h4l5-4v14l-5-4H4z M17 8a6 6 0 0 1 0 8 M20 5a10 10 0 0 1 0 14',
  reset:'M3 10a9 9 0 1 1 1 8 M3 3v7h7',
  menu:'M4 6h16 M4 12h16 M4 18h16',
  upload:'M12 16V3 m-5 5 5-5 5 5 M4 16v5h16v-5',
  star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',
};
function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;}
let state={view:'briefing',missionId:'orbiter',design:normalizeDesign(null),mode:'explorer',category:'engine',flight:null,archive:[],name:'Hail Mary I',sound:false};
let storageAvailable=true;
let reviewIndex=null;
const currentFlight=()=>reviewIndex===null?state.flight:state.archive[reviewIndex]?.flight;
try{
  const saved=JSON.parse(localStorage.getItem(KEY)||'null');
  if(saved&&saved.version===1){
    state.missionId=getMission(saved.missionId).id;state.design=normalizeDesign(saved.design,state.missionId);
    state.mode=saved.mode==='commander'?'commander':'explorer';state.name=typeof saved.name==='string'?saved.name.slice(0,40):state.name;
    state.flight=restoreFlight(saved.flight);state.archive=Array.isArray(saved.archive)?saved.archive.slice(0,12).map(x=>({...x,flight:restoreFlight(x.flight)})).filter(x=>x.flight&&x.flight.complete):[];
  }
}catch{storageAvailable=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify({...state,version:1}));}catch{storageAvailable=false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function sound(){if(!state.sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.setValueAtTime(660,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(880,ctx.currentTime+.12);g.gain.setValueAtTime(.04,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.start();o.stop(ctx.currentTime+.2);o.onended=()=>ctx.close();}catch{}}
const nav=[['briefing','grid','Mission desk'],['builder','sliders','Spacecraft lab'],['flight','radio','Flight console'],['archive','archive','Mission archive'],['learn','book','Field manual']];
function shell(content){
  const m=getMission(state.missionId), c=calculate(state.design,state.missionId,state.mode);
  return `<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="briefing"><img src="./assets/emblem.svg" alt=""/><span>HAIL MARY<small>MISSION CONTROL</small></span></a>
    <div class="workspace-label">YOUR WORKSPACE</div><nav aria-label="Main navigation">${nav.map(([view,i,label])=>`<button class="nav-item ${state.view===view?'active':''}" data-action="nav" data-view="${view}" ${state.view===view?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${view==='flight'&&state.flight&&!state.flight.complete?'<i class="live-dot"></i>':''}</button>`).join('')}</nav>
    <div class="sidebar-bottom"><div class="orbit-badge">${icon('globe',30)}<span>Small team.<br>Extraordinary mission.</span></div><div class="sidebar-foot">A NASA Space Apps project<br><strong>TEAM HAIL MARY <span>↗</span></strong></div></div></aside>
    <div class="workspace"><header class="topbar"><div class="breadcrumb">MISSION CONTROL <span>/</span> <strong>${nav.find(n=>n[0]===state.view)?.[2]||'Debrief'}</strong></div><div class="header-actions"><span class="saved-indicator"><i></i>${storageAvailable?'Saved on this device':'Session only'}</span><button class="icon-button" data-action="sound" aria-label="${state.sound?'Mute':'Enable'} interface sound" aria-pressed="${state.sound}">${icon('volume')}</button><button class="avatar" data-action="about" aria-label="About Hail Mary">HM</button></div></header>
    <main id="main" tabindex="-1">${content}</main><footer class="footer"><span><i class="live-dot"></i> Built for the next great leap.</span><button data-action="nav" data-view="learn">NASA sources & simulation notes ${icon('arrow',14)}</button><span>HAIL MARY / 2026</span></footer></div>`;
}
function eyebrow(text){return `<div class="eyebrow"><span></span>${text}</div>`;}
function button(text,action,iconName='arrow',extra='',cls='primary'){return `<button class="button ${cls}" data-action="${action}" ${extra}>${text}${icon(iconName,18)}</button>`;}
function moonVisual(size=''){return `<div class="moon-visual ${size}" aria-label="Illustrated Moon using NASA LRO imagery" role="img"><div class="moon-orbit orbit-one"></div><div class="moon-orbit orbit-two"></div><canvas class="moon-globe" aria-hidden="true"></canvas><span class="moon-pin"><i></i> LUNAR NORTH POLE</span><span class="moon-coordinate">90° N / THE NEXT FRONTIER</span><span class="orbit-probe">${icon('spark',16)}</span><div class="moon-scale"><span>←</span> 3,474.8 KM DIAMETER <span>→</span></div></div>`;}
function briefing(){
  const m=getMission(state.missionId);
  return `<section class="page-heading"><div>${eyebrow('YOUR NEXT CHAPTER IS OUT THERE')}<h1>Mission desk<span class="heading-dot">.</span></h1></div><span class="outline-tag">LUNAR PROGRAM / 01</span></section>
    <section class="hero panel"><div class="hero-copy"><span class="label mint">DESIGN. DECIDE. DISCOVER.</span><h2>The Moon<br>is waiting.</h2><p>Build your spacecraft. Make the hard calls.<br>Bring the science home.</p><div class="hero-actions">${button('Design your mission','nav','arrow','data-view="builder"')}<button class="text-button" data-action="guide">How to play ${icon('info',15)}</button></div><div class="hero-caption"><span>01 — 03</span> THREE MISSIONS. YOUR CALL.</div></div>${moonVisual()}<div class="hero-source">LUNAR IMAGERY · NASA / LRO</div></section>
    <section class="mission-section"><div class="section-title"><div><span class="label">CHOOSE YOUR OBJECTIVE</span><h2>Every mission starts with a why.</h2></div><span class="muted small">Select a mission to explore</span></div><div class="mission-grid">${MISSIONS.map(x=>`<button class="mission-card ${m.id===x.id?'selected':''}" data-action="select-mission" data-id="${x.id}" aria-pressed="${m.id===x.id}"><div class="mission-card-top"><span class="mission-number">${x.number}</span><span class="tag ${x.accent}">${x.tag}</span></div><div class="mission-orbit-art ${x.id}" aria-hidden="true"><i></i><span></span><b></b></div><span class="label">${x.type}</span><h3>${x.name}${m.id===x.id?icon('check',20):icon('arrow',20)}</h3><p>${x.description}</p><div class="mission-card-bottom"><span>${icon('clock',14)}${x.days} days</span><span>$${x.budget}M budget</span><span>${x.difficulty}</span></div></button>`).join('')}</div></section>
    <section class="briefing-bottom"><div class="panel mission-brief"><div class="section-title"><span class="label">MISSION BRIEF / ${m.number}</span><span class="mint">${icon('flag',19)}</span></div><h3>${m.objective}</h3><p>${m.detail}</p><div class="brief-facts"><div><small>DESTINATION</small><strong>The Moon</strong></div><div><small>BASE ΔV</small><strong>${fmt(m.dv)} <span>m/s</span></strong></div><div><small>KEY INSTRUMENT</small><strong>${getPart('payload',m.required).name}</strong></div></div></div><div class="panel mode-panel"><span class="label">CHOOSE YOUR SEAT</span><h3>A little guidance, or full command?</h3><div class="mode-switch" aria-label="Difficulty">${[['explorer','Explorer','Standard budget · 200 m/s reserve'],['commander','Commander','5% less budget · 400 m/s reserve']].map(([id,title,desc])=>`<button class="${state.mode===id?'selected':''}" data-action="mode" data-id="${id}" aria-pressed="${state.mode===id}"><span>${title}</span><small>${desc}</small></button>`).join('')}</div><p class="tiny muted">Both modes use the same physics. Your choices change the outcome.</p></div></section>`;
}
function meter(label,value,unit,percent,good=true,sub=''){return `<div class="metric"><div class="metric-label">${label}<span class="${good?'mint':'amber'}">${good?'NOMINAL':'ATTENTION'}</span></div><div class="metric-value">${value}<span>${unit}</span></div><div class="meter-track"><i class="${good?'':'warn'}" style="width:${Math.max(1,Math.min(100,percent))}%"></i></div><small>${sub}</small></div>`;}
function spacecraft(){return `<div class="spacecraft" aria-label="Schematic of selected spacecraft" role="img"><svg viewBox="0 0 560 330" aria-hidden="true"><defs><linearGradient id="body" x1="0" x2="1"><stop stop-color="#9b8d66"/><stop offset=".45" stop-color="#e4d8ad"/><stop offset="1" stop-color="#85754f"/></linearGradient><pattern id="cells" width="21" height="18" patternUnits="userSpaceOnUse"><rect width="20" height="17" fill="#233e4c" stroke="#5e8190" stroke-width=".5"/></pattern></defs><ellipse cx="280" cy="270" rx="160" ry="18" fill="#000" opacity=".25"/><g transform="translate(280 165) rotate(-18)"><path d="M-170 0H170" stroke="#89969b" stroke-width="5"/><path d="M-202-48h148v96h-148z M54-48h148v96H54z" fill="url(#cells)" stroke="#8196a0" stroke-width="3"/><path d="m-42-50 32-16 53 17v96l-39 16-46-20z" fill="url(#body)" stroke="#c5b88d" stroke-width="2"/><path d="M-10-66v99L4 63 M-42-50-10-34 43-49 M-42 15l85-23" fill="none" stroke="#7c704e" stroke-width="1.5"/><path d="M-25 54-33 82H22L13 59" fill="#8d999d" stroke="#b5c0c1"/><path d="M-33 82c14 10 42 10 55 0" fill="#364148" stroke="#99a9af"/><path d="M12-64v-30 M-19-94c3 22 53 22 63 0Z" fill="#c6cfd0" stroke="#e2e6dd"/><path d="M12-94 26-117" stroke="#e1e9de" stroke-width="2"/><circle cx="26" cy="-117" r="3" fill="#d5f5b9"/><rect x="13" y="-12" width="20" height="25" rx="4" fill="#2b3537" stroke="#a8b9ba"/><circle cx="23" cy="0" r="7" fill="#171e23" stroke="#6f98a9"/>${state.missionId==='lander'?'<path d="m-38 35-40 60h-15 m128-60 40 60h15" fill="none" stroke="#c5c9b6" stroke-width="4"/>':''}</g><g fill="#809199" font-family="monospace" font-size="9"><text x="35" y="35">${escape(state.design.power.toUpperCase())} ARRAY</text><text x="394" y="46">${escape(state.design.comms.toUpperCase())} LINK</text><text x="390" y="294">${escape(getPart('engine',state.design.engine).name.toUpperCase())}</text></g><g stroke="#596970" stroke-width=".6" fill="none"><path d="m118 43 15 31v42 M455 54h-85l-55 23 M425 278h-68l-50-45"/></g></svg><span class="schematic-label">CONFIGURATION PREVIEW · NOT TO SCALE</span></div>`;}
function advisor(c){const failures=c.checks.filter(x=>!x.pass);if(failures.length)return {title:`${failures.length} item${failures.length>1?'s':''} before we fly`,text:failures[0].tip};if(c.dataFraction<1)return {title:'Your downlink is the bottleneck',text:`Only ${Math.round(c.dataFraction*100)}% of instrument data fits the link. A larger antenna can increase science return.`};if(c.generation-c.draw<150)return {title:'Ready, with a narrow power margin',text:'The array fault in flight may force a trade-off. Consider a larger array or plan a recovery maneuver.'};return {title:'Your design is ready for flight',text:`You have ${fmt(c.dv-c.mission.dv)} m/s beyond the planned route. Keep some in reserve for the unexpected.`};}
function builder(){const c=calculate(state.design,state.missionId,state.mode),cat=CATEGORIES.find(x=>x.id===state.category),advice=advisor(c);
  return `<section class="page-heading"><div>${eyebrow(`${c.mission.name.toUpperCase()} / ${state.mode.toUpperCase()} MODE`)}<h1>Build for the journey<span class="heading-dot">.</span></h1></div><div class="heading-actions"><button class="icon-button" data-action="import" aria-label="Import spacecraft design">${icon('upload')}</button><button class="icon-button" data-action="export-design" aria-label="Export spacecraft design">${icon('download')}</button>${button('Share design','share','share','','secondary')}</div></section>
  <div class="builder-metrics">${meter('MISSION COST',`$${fmt(c.cost,1)}`,'M',c.cost/c.budget*100,c.cost<=c.budget,`of $${fmt(c.budget,1)}M budget`)}${meter('AVAILABLE ΔV',fmt(c.dv),'m/s',c.dv/c.requiredDv*100,c.dv>=c.requiredDv,`${fmt(c.requiredDv)} m/s required, including reserve`)}${meter('WET MASS',fmt(c.wet),'kg',c.wet/c.launcher.massLimit*100,c.wet<=c.launcher.massLimit,`${fmt(c.launcher.massLimit)} kg launch capacity`)}${meter('POWER BALANCE',`${c.generation-c.draw>=0?'+':''}${fmt(c.generation-c.draw)}`,'W',c.draw/c.generation*100,c.generation>=c.draw,`${c.draw} W demand / ${fmt(c.generation)} W available`)}</div>
  <div class="builder-layout"><div class="builder-main"><section class="panel craft-panel"><div class="craft-panel-head"><div><label class="label" for="mission-name">YOUR SPACECRAFT</label><input class="name-input" id="mission-name" data-field="name" maxlength="40" value="${escape(state.name)}" aria-label="Spacecraft name"/></div><span class="outline-tag">ROBOTIC / ${c.mission.type.toUpperCase()}</span></div>${spacecraft()}<div class="craft-stats"><span>${icon('scan',16)}${c.payload.length} science instrument${c.payload.length!==1?'s':''}</span><span>${icon('battery',16)}${fmt(c.usableEnergy/c.draw,1)} h eclipse endurance</span><span>${icon('chart',16)}${fmt(c.science)} planned science</span></div></section>
  <section class="panel parts-panel"><div class="category-tabs" role="group" aria-label="Spacecraft systems">${CATEGORIES.map(x=>`<button class="${state.category===x.id?'active':''}" data-action="category" data-id="${x.id}" aria-pressed="${state.category===x.id}">${icon(x.icon,17)}${x.name}</button>`).join('')}</div><div class="parts-heading"><div><span class="label">CONFIGURE YOUR ${cat.name.toUpperCase()}</span><p>${state.category==='payload'?'Select any combination. Every instrument adds mass and power demand.':'Choose one system. Watch the mission margins respond.'}</p></div></div><div class="part-list">${PARTS[state.category].map(p=>{const selected=state.category==='payload'?state.design.payload.includes(p.id):state.design[state.category]===p.id;return `<button class="part-card ${selected?'selected':''}" data-action="part" data-id="${p.id}" aria-pressed="${selected}"><span class="selection-box ${state.category==='payload'?'square':''}">${selected?icon('check',13):''}</span><div class="part-copy"><strong>${p.name}</strong><span>${p.subtitle}</span><p>${p.description}</p></div><div class="part-numbers"><strong>$${p.cost}M</strong><span>${p.mass?`${fmt(p.mass)} kg`:`${fmt(p.massLimit)} kg capacity`}</span></div></button>`;}).join('')}</div></section>
  <section class="panel fuel-panel"><div class="section-title"><div><span class="label">PROPELLANT LOAD</span><h3>Fuel is freedom. And mass.</h3></div><div class="fuel-number"><input type="number" id="fuel-number" aria-label="Propellant mass in kilograms" data-field="fuel" min="500" max="10000" step="100" value="${state.design.fuel}"/><span>kg</span></div></div><input class="fuel-slider" type="range" id="fuel-range" aria-label="Propellant load" min="500" max="10000" step="100" value="${state.design.fuel}" data-field="fuel"/><div class="range-labels"><span>500 kg · lean</span><span>10,000 kg · long reach</span></div><p class="tiny muted">${fmt(c.dry)} kg dry spacecraft + ${fmt(state.design.fuel)} kg propellant = ${fmt(c.wet)} kg to launch. Propellant costs $1,500/kg in the game.</p></section></div>
  <aside class="preflight panel"><div class="section-title"><span class="label">PREFLIGHT CHECK</span><span class="check-count ${c.ready?'mint':'amber'}">${c.passed}/6</span></div><h3>${c.ready?'All systems go.':'Let’s get flight-ready.'}</h3><p class="muted small">${c.mission.name} · ${c.mission.days}-day mission</p><div class="checks">${c.checks.map(x=>`<div class="check-row ${x.pass?'pass':'fail'}"><span class="check-icon">${icon(x.pass?'check':'info',14)}</span><div><strong>${x.label}</strong><small>${x.value}</small>${!x.pass?`<p>${x.tip}</p>`:''}</div></div>`).join('')}</div><div class="advisor"><div>${icon('spark',17)}<span>FLIGHT DIRECTOR</span></div><strong>${advice.title}</strong><p>${advice.text}</p><small>Rule-based guidance · explains your margins</small></div>${button('Enter flight console','launch','rocket',c.ready?'':'disabled','primary full')}<p class="tiny muted center">${c.ready?'Launch begins in low Earth orbit.':'Resolve every check to unlock launch.'}</p><button class="text-button center full" data-action="reset-design">${icon('reset',14)} Restore mission starter</button></aside></div>`;
}
function trajectory(f){const p=[.03,.28,.55,.84,1,1][f.step];return `<div class="trajectory"><div class="trajectory-top"><span class="label">LIVE MISSION SCHEMATIC</span><span class="tag mint"><i class="live-dot"></i>${f.complete?'FLIGHT ENDED':'AWAITING YOUR COMMAND'}</span></div><svg viewBox="0 0 800 280" role="img" aria-label="Schematic journey from Earth to the Moon, not to scale"><defs><radialGradient id="earth"><stop stop-color="#6a9db5"/><stop offset=".7" stop-color="#294b68"/><stop offset="1" stop-color="#122334"/></radialGradient><linearGradient id="route"><stop stop-color="#cdf6b1" stop-opacity=".2"/><stop offset="1" stop-color="#cdf6b1"/></linearGradient></defs><g stroke="#263238" fill="none"><ellipse cx="100" cy="155" rx="76" ry="33" transform="rotate(-22 100 155)"/><ellipse cx="705" cy="100" rx="65" ry="45" transform="rotate(-25 705 100)"/></g><path d="M100 155C290 -10 535 10 705 100" fill="none" stroke="#40504e" stroke-width="1.5" stroke-dasharray="4 7"/><path d="M100 155C290 -10 535 10 705 100" fill="none" stroke="url(#route)" stroke-width="2" pathLength="100" stroke-dasharray="${p*100} 100"/><circle cx="100" cy="155" r="38" fill="url(#earth)"/><path d="m83 123 15 12-4 18 19 8-9 18-17-7-6-22-10-5" fill="#799685" opacity=".65"/><circle cx="705" cy="100" r="26" fill="#969d94"/><circle cx="696" cy="91" r="6" fill="#737b73"/><circle cx="714" cy="109" r="8" fill="#818980"/><g fill="#83949b" font-family="monospace" font-size="11"><text x="77" y="222">EARTH</text><text x="686" y="155">MOON</text><text x="310" y="242">384,400 KM · MEAN DISTANCE</text></g><g transform="translate(${100+605*p} ${155*(1-p)*(1-p)-70*p*(1-p)+100*p*p})"><circle r="17" fill="#cdf6b1" opacity=".07"/><circle r="9" fill="#cdf6b1" opacity=".15"/><path d="m-7 5 5-11 11 4-8 3-3 8Z" fill="#d5f9bc"/></g></svg><span class="tiny muted">Illustrative route and progress; not an orbital propagation.</span></div>`;}
function flight(){const f=currentFlight();if(!f)return `<section class="empty-state panel">${icon('radio',48)}${eyebrow('FLIGHT CONSOLE')}<h1>Your mission starts in the lab.</h1><p>Build a flight-ready spacecraft, then take command of the journey.</p>${button('Open spacecraft lab','nav','arrow','data-view="builder"')}</section>`;
  const c=calculate(f.design,f.missionId,f.mode),stage=FLIGHT_STAGES[f.step],summary=summarize(f);
  if(f.complete)return debrief(f);
  return `<section class="page-heading"><div>${eyebrow(`FLIGHT ACTIVE / ${c.mission.name.toUpperCase()}`)}<h1>You have the controls<span class="heading-dot">.</span></h1></div><span class="outline-tag">COMMAND ${f.step+1} / 5</span></section>
  <div class="flight-progress">${FLIGHT_STAGES.slice(0,5).map((s,i)=>`<div class="${i<f.step?'done':i===f.step?'current':''}"><span>${i<f.step?icon('check',14):`0${i+1}`}</span>${s.short}</div>`).join('')}</div>
  <div class="flight-layout"><div><section class="panel">${trajectory(f)}</section><section class="panel command-panel"><div class="section-title"><span class="label">COMMAND REQUIRED / 0${f.step+1}</span>${icon('radio',19)}</div><h2>${stage.name}</h2><p>${stage.description}</p><div class="command-options">${flightChoices(f).map((x,i)=>`<button class="command-card" data-action="flight-command" data-id="${x.id}"><span class="command-letter">${String.fromCharCode(65+i)}</span><div><strong>${x.title}</strong><small>${x.detail}</small></div>${icon('arrow',20)}</button>`).join('')}</div></section></div><aside class="panel telemetry"><span class="label">SPACECRAFT TELEMETRY</span><h3>${escape(f.name||state.name)}</h3><div class="telemetry-readout"><small>PROPELLANT REMAINING</small><strong>${fmt(f.fuel)}<span>kg</span></strong><div class="meter-track"><i style="width:${f.fuel/f.design.fuel*100}%"></i></div></div><div class="telemetry-readout"><small>REMAINING ΔV</small><strong>${fmt(remainingDv(f))}<span>m/s</span></strong></div><div class="telemetry-readout"><small>AVAILABLE SOLAR POWER</small><strong>${fmt(c.generation*f.generationFactor)}<span>W</span></strong><small>${c.draw} W full-operation demand</small></div><div class="telemetry-pair"><span>Planned science retained</span><strong>${fmt(f.scienceFactor*100)}%</strong></div><div class="telemetry-pair"><span>Schedule extension</span><strong>+${f.extraHours} h</strong></div><div class="advisor"><div>${icon('spark',17)}<span>FLIGHT DIRECTOR</span></div><p>${flightAdvice(f,c)}</p></div><button class="text-button full" data-action="abort">End flight & return to lab</button></aside></div>
  ${flightLog(f)}`;
}
function flightAdvice(f,c){const future=f.step<3?c.mission.capture+c.mission.landing:0;return f.step===0?'Your launch service has already placed the spacecraft in Earth orbit. The next burn uses your spacecraft’s propellant.':f.step===2?`After preserving ${fmt(future)} m/s for arrival, you have ${fmt(remainingDv(f)-future)} m/s for recovery and reserve. Compare that with the 80 m/s recovery cost.`:f.step===4?`Your link accommodates ${fmt(c.dataFraction*100)}% of the instrument data. Your next choice applies to that planned return.`:`Arrival requires ${fmt(future)} m/s. Every burn uses propellant according to your current mass and engine efficiency.`;}
function flightLog(f){return `<section class="panel flight-log"><div class="section-title"><h3>Flight log</h3><span class="label">${f.log.length} RECORDED COMMAND${f.log.length!==1?'S':''}</span></div>${f.log.length?`<div class="table-scroll"><table><thead><tr><th>PHASE</th><th>COMMAND</th><th>ΔV</th><th>PROPELLANT</th></tr></thead><tbody>${f.log.map(l=>`<tr><td>${l.stage}</td><td><strong>${l.command}</strong><small>${l.result}</small></td><td>${fmt(l.dv)} m/s</td><td>${fmt(l.fuel,1)} kg</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Your first command will appear here. Every decision is recorded.</p>'}</section>`;}
function fuelChart(f){const max=f.design.fuel;return `<svg class="fuel-chart" viewBox="0 0 600 190" role="img" aria-label="Propellant remaining after each mission phase"><line x1="45" y1="148" x2="580" y2="148" stroke="#344147"/><line x1="45" y1="25" x2="580" y2="25" stroke="#263238" stroke-dasharray="3 5"/><text x="2" y="29" fill="#829399" font-size="10">${fmt(max)}</text><text x="23" y="152" fill="#829399" font-size="10">0</text>${f.history.map((h,i)=>{const x=60+i*88, height=h.fuel/max*115;return `<rect x="${x}" y="${148-height}" width="40" height="${Math.max(1,height)}" rx="3" fill="${i===f.history.length-1?'#cdf6b1':'#496050'}"/><text x="${x+20}" y="${140-height}" text-anchor="middle" fill="#dbe5dc" font-size="10">${fmt(h.fuel)}</text><text x="${x+20}" y="171" text-anchor="middle" fill="#829399" font-size="9">${h.stage}</text>`;}).join('')}</svg>`;}
function debrief(f){const s=summarize(f),c=calculate(f.design,f.missionId,f.mode);return `<section class="page-heading"><div>${eyebrow(`${c.mission.name.toUpperCase()} / FLIGHT DEBRIEF`)}<h1>Every choice brought you here<span class="heading-dot">.</span></h1></div>${button('Download report','export-report','download','','secondary')}</section>
  <section class="panel result-hero"><div class="result-emblem">${icon(s.objectiveMet?'flag':'book',44)}</div><div><span class="label ${s.objectiveMet?'mint':'amber'}">${s.objectiveMet?'SCIENCE OBJECTIVE ACHIEVED':'A FLIGHT TO LEARN FROM'}</span><h2>${f.failed?'Mission ended early.':s.objectiveMet?'A small spacecraft. A real achievement.':'The journey is complete. Keep refining.'}</h2><p>${s.objectiveMet?`Your ${c.mission.type.toLowerCase()} returned ${fmt(s.science,1)} science points against a target of ${c.mission.minScience}.`:'Review your design and flight decisions, then try a different balance of capability and resources.'}</p></div><div class="score-ring"><strong>${s.score}</strong><span>MISSION SCORE</span></div></section>
  <div class="debrief-metrics"><div><small>SCIENCE RETURN</small><strong>${fmt(s.science,1)}<span>points</span></strong></div><div><small>MISSION COST</small><strong>$${fmt(s.cost,1)}<span>M</span></strong></div><div><small>FINAL ΔV RESERVE</small><strong>${fmt(s.reserve)}<span>m/s</span></strong></div><div><small>MISSION DURATION</small><strong>${fmt(s.duration/24,1)}<span>days</span></strong></div></div>
  <div class="debrief-columns"><section class="panel chart-panel"><span class="label">THE COST OF GETTING THERE</span><h3>Your propellant, burn by burn.</h3>${fuelChart(f)}<p class="tiny muted">Remaining propellant in kilograms. Sequential burns use the rocket equation.</p></section><section class="panel lessons"><span class="label">WHAT YOUR MISSION TAUGHT YOU</span><h3>Bring the learning home.</h3><div class="lesson">${icon('flame',19)}<p><strong>Mass travels with you.</strong> Your ${fmt(c.dry)} kg dry spacecraft needed ${fmt(f.design.fuel-f.fuel)} kg of propellant for the selected burns.</p></div><div class="lesson">${icon('radio',19)}<p><strong>Science needs a way home.</strong> Your link supported ${fmt(c.dataFraction*100)}% of instrument data; flight choices retained ${fmt(f.scienceFactor*100)}% of that plan.</p></div><div class="lesson">${icon('sun',19)}<p><strong>Margin buys choices.</strong> ${f.decisions.includes('repair')?'You spent fuel to restore power and protect your science plan.':f.decisions.includes('shed')?'You accepted reduced solar power; available power determined the science penalty.':'You traded time and some science coverage to recover array output.'}</p></div><p class="tiny muted">Score: up to 65 science + 20 budget efficiency + 15 fuel reserve. See the Field manual for the formula.</p></section></div>
  <div class="debrief-actions">${button('Refine this spacecraft','refine','sliders')}${button('Choose another mission','nav','arrow','data-view="briefing"','secondary')}</div>${flightLog(f)}`;}
function archive(){return `<section class="page-heading"><div>${eyebrow('YOUR EXPLORATION RECORD')}<h1>Mission archive<span class="heading-dot">.</span></h1></div><span class="outline-tag">${state.archive.length} COMPLETED FLIGHTS</span></section>${state.archive.length?`<div class="archive-grid">${state.archive.map((entry,i)=>{const s=summarize(entry.flight),m=getMission(entry.flight.missionId);return `<article class="panel archive-card"><div class="section-title"><span class="label">${escape(m.type)}</span><span class="mint">${icon(s.objectiveMet?'flag':'book',20)}</span></div><h2>${escape(entry.name||m.name)}</h2><p class="muted">${m.name} · ${entry.flight.mode}</p><div class="archive-score"><strong>${s.score}<small>/100</small></strong><span>${s.objectiveMet?'Objective achieved':'Learning flight'}</span></div><div class="archive-details"><span>Science <strong>${fmt(s.science,1)}</strong></span><span>Cost <strong>$${fmt(s.cost,1)}M</strong></span><span>Reserve <strong>${fmt(s.reserve)} m/s</strong></span></div><button class="button secondary full" data-action="open-archive" data-index="${i}">Review flight ${icon('arrow',18)}</button></article>`;}).join('')}</div><p class="tiny muted">The latest 12 completed flights are stored on this device. Download reports to keep a permanent copy.</p>`:`<section class="empty-state panel">${icon('archive',48)}<h2>A clean flight log. An open horizon.</h2><p>Complete your first mission to compare its science, cost, and fuel reserve here.</p>${button('Build your first spacecraft','nav','arrow','data-view="builder"')}</section>`}`;}
function learn(){return `<section class="page-heading"><div>${eyebrow('UNDERSTAND THE DECISIONS')}<h1>Your field manual<span class="heading-dot">.</span></h1></div><span class="outline-tag">OPEN SCIENCE. CLEAR ASSUMPTIONS.</span></section><section class="manual-intro panel"><div>${icon('book',35)}<h2>Space is hard.<br>The principles are within reach.</h2></div><p>Hail Mary is an educational mission-design game. You balance mass, propulsion, power, communications, and science, then make decisions during a repeatable flight scenario. These are simplified engineering models, not flight-qualified mission plans.</p></section><div class="manual-grid">${[
  ['01','Velocity budget, not speed','Delta-v (Δv) is how much your spacecraft can change its velocity. It is a capability budget, not your current speed. A more efficient engine or lower dry mass increases it.','Δv = Isp × 9.80665 × ln(wet / dry)'],
  ['02','Mass is a mission-wide decision','Dry mass includes the spacecraft bus, systems, instruments, and a landing package when needed. Wet mass adds propellant. The rocket equation is recalculated after every burn.','Propellant used = mass × (1 − e^(−Δv / (Isp × g₀)))'],
  ['03','Power and energy are different','Watts measure instantaneous power. Watt-hours measure stored energy. Solar output is derated to 80% of nominal; batteries offer 80% usable capacity. Eclipse checks assume zero solar input.','Eclipse requirement (Wh) = load (W) × shadow time (h)'],
  ['04','More instruments ≠ more science','Instrument values depend on the mission. A spectrometer is especially useful for the polar survey; radar is prioritized for the lander. Downlink capacity can limit the return.','Planned science = weighted payload value × downlink fraction'],
  ['05','A reserve is a decision budget','Preflight requires 200 m/s beyond the planned route in Explorer mode and 400 m/s in Commander mode. Recovery costs 80 m/s. Commander also cuts the available budget by 5%.','Useful margin = available Δv − planned route Δv'],
  ['06','What the score rewards','Science contributes up to 65 points: min(65, science / target × 45). Budget efficiency contributes up to 20: clamp((1 − cost / budget) × 50 + 10, 0, 20). Reserve contributes up to 15: clamp(reserve / 300 × 15, 0, 15).','Mission score = science + budget efficiency + reserve']
].map(([n,t,p,e])=>`<article class="panel manual-card"><span class="mission-number">${n}</span><h3>${t}</h3><p>${p}</p><div class="formula">${e}</div></article>`).join('')}</div><section class="panel assumptions"><span class="label">WHERE THE SIMULATION DRAWS THE LINE</span><h2>Real principles. An intentionally small universe.</h2><ul><li>The launch service delivers the spacecraft to low Earth orbit. The player’s propulsion budget starts there; ascent is not simulated.</li><li>We use NASA’s approximate 3,200 m/s departure and 1,350 m/s polar capture values. A 100 m/s cruise allowance and 1,850 m/s landing allowance are game assumptions. Flyby: 3,300 m/s; orbiter: 4,650 m/s; lander: 6,500 m/s, before reserve.</li><li>All component names, masses, engine efficiencies, prices, electrical loads, instrument scores, downlink capacities, and scenario timings are authored game parameters. The launch vehicles are fictional capacity classes, not real vehicle performance claims.</li><li>Flight duration is an authored schedule. The map is schematic; there is no live ephemeris, launch-window search, gravity integration, terrain avoidance, or landing guidance.</li><li>Burns are instantaneous. Tanks and structure are part of fixed dry mass. Cryogenic boil-off, thermal effects, structural loads, and real radio link budgets are not modeled.</li><li>Solar output is constant before scenario modifiers. Eclipse energy is verified at preflight, not integrated over time. Surface operations assume daylight, not survival through a lunar night.</li><li>The flight scenario is deterministic. Replay the same commands with the same design and get the same result. The flight director is rule-based, not a generative AI service.</li><li>All progress stays in this browser. There is no account, tracking service, API key, or server database.</li></ul></section><section class="sources-section"><div class="section-title"><div><span class="label">BUILT ON NASA’S OPEN KNOWLEDGE</span><h2>Follow the science.</h2></div></div><div class="sources-list">${SOURCES.map((s,i)=>`<a class="panel source-row" href="${s.url}" target="_blank" rel="noopener noreferrer"><span class="source-index">0${i+1}</span><div><span class="label">${s.publisher}</span><h3>${s.title}</h3><p>${s.use}</p></div>${icon('arrow',22)}</a>`).join('')}</div><p class="tiny muted">Lunar visualization: NASA SVS / Ernie Wright, using LRO data. Independent project by Team Hail Mary; no NASA endorsement is implied. All scientific inputs are bundled reference values, not live data.</p></section>`;}
function render(){document.querySelectorAll('.moon-globe').forEach(c=>c.releaseGlobe?.());const views={briefing,builder,flight,archive,learn};$('#app').innerHTML=shell((views[state.view]||briefing)());document.title=`${state.view==='flight'&&currentFlight()?.complete?'Flight debrief':nav.find(n=>n[0]===state.view)?.[2]||'Mission Control'} — Hail Mary`;document.querySelectorAll('.moon-globe').forEach(mountGlobe);save();}
function navigate(view){reviewIndex=null;state.view=view;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function modal(title,body,actions=''){const d=$('#modal');d.innerHTML=`<div class="modal-top"><span class="label">HAIL MARY / MISSION CONTROL</span><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><h2 id="modal-title">${title}</h2>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}`;d.showModal();}
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function downloadReport(){const f=currentFlight();if(!f?.complete)return;const s=summarize(f),c=calculate(f.design,f.missionId,f.mode);const report=`# Hail Mary — Flight Report\n\nSpacecraft: ${f.name||state.name}\nMission: ${c.mission.name} (${c.mission.type})\nMode: ${f.mode}\nObjective: ${s.objectiveMet?'Achieved':'Not achieved'}\nScore: ${s.score}/100\nScience: ${s.science.toFixed(1)} / ${c.mission.minScience} target\nCost: $${s.cost.toFixed(1)}M\nDuration: ${s.duration} hours\nRemaining propellant: ${f.fuel.toFixed(1)} kg\nRemaining delta-v: ${s.reserve.toFixed(1)} m/s\n\n## Spacecraft configuration\n\n${Object.entries(f.design).map(([k,v])=>`${k}: ${Array.isArray(v)?v.join(', '):v}`).join('\n')}\n\n## Command log\n\n${f.log.map(l=>`### ${l.stage}\n${l.command}\n${l.result}\nDelta-v: ${l.dv} m/s; propellant used: ${l.fuel.toFixed(1)} kg.`).join('\n\n')}\n\n## Sources\n\n${SOURCES.map(s=>`${s.title}: ${s.url}\n${s.use}`).join('\n\n')}\n\nEducational simulation. Component specifications, prices, scores, and events are authored game assumptions. Burns use NASA's ideal rocket equation. Trajectories are schematic; this is not a mission planning or operational safety tool.\n`;download('hail-mary-flight-report.md',report,'text/markdown');toast('Flight report downloaded.');}
async function shareDesign(){const payload={v:1,missionId:state.missionId,mode:state.mode,design:state.design,name:state.name};const url=new URL(location.href);url.hash='design='+encodeURIComponent(JSON.stringify(payload));try{await navigator.clipboard.writeText(url.href);toast('Design link copied. Your teammate can open the same spacecraft.');}catch{modal('Share this spacecraft',`<p>Copy this link to share your mission configuration.</p><textarea class="share-url" readonly aria-label="Shareable design URL">${escape(url.href)}</textarea>`);} }
function applyImport(data){if(!data||data.v!==1||!MISSIONS.some(m=>m.id===data.missionId)||!data.design||typeof data.design!=='object')throw new Error('Use a Hail Mary v1 design file.');state.missionId=data.missionId;state.design=normalizeDesign(data.design,data.missionId);state.mode=data.mode==='commander'?'commander':'explorer';state.name=typeof data.name==='string'?data.name.slice(0,40):'Imported spacecraft';navigate('builder');toast('Spacecraft design loaded. Review the preflight checks.');}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;e.preventDefault();const a=target.dataset.action;
  if(a==='nav'){navigate(target.dataset.view);return;}
  if(a==='close-modal'){$('#modal').close();return;}
  if(a==='sound'){state.sound=!state.sound;render();sound();toast(state.sound?'Interface sound enabled.':'Interface sound muted.');return;}
  if(a==='about'){modal('Small team. Extraordinary mission.',`<p>We’re Team Hail Mary. This game makes the trade-offs behind a space mission something you can see, change, and learn from.</p><p>Built for NASA Space Apps: Space Mission Design Game. Start with a mission, design your spacecraft, and bring the science home.</p><p class="tiny muted">Independent educational project. NASA sources and authored assumptions are listed in the Field manual.</p>`);return;}
  if(a==='guide'){modal('Five minutes to your first mission.',`<ol class="guide-list"><li><strong>Choose a purpose.</strong> Select a flyby, polar orbiter, or robotic lander.</li><li><strong>Build your spacecraft.</strong> Pick systems and instruments. Adjust fuel until all six preflight checks pass.</li><li><strong>Take command.</strong> Fly through five decision points. Trade fuel, time, power, and science.</li><li><strong>Learn and try again.</strong> Read the debrief, download your report, and compare flights in the archive.</li></ol><p class="tiny muted">Starter configurations give you a working baseline. No account or API key required.</p>`,button('Go to spacecraft lab','start-guide'));return;}
  if(a==='start-guide'){$('#modal').close();navigate('builder');return;}
  if(a==='select-mission'){if(state.missionId===target.dataset.id)return;state.missionId=target.dataset.id;state.design=normalizeDesign(null,state.missionId);render();toast(`${getMission(state.missionId).name} selected. Starter spacecraft loaded.`);return;}
  if(a==='mode'){state.mode=target.dataset.id;render();return;}
  if(a==='category'){state.category=target.dataset.id;render();document.querySelector(`[data-action="category"][data-id="${state.category}"]`)?.focus({preventScroll:true});return;}
  if(a==='part'){const cat=state.category,id=target.dataset.id;if(cat==='payload')state.design.payload=state.design.payload.includes(id)?state.design.payload.filter(x=>x!==id):[...state.design.payload,id];else state.design[cat]=id;render();document.querySelector(`[data-action="part"][data-id="${id}"]`)?.focus({preventScroll:true});return;}
  if(a==='reset-design'){modal('Restore the starter spacecraft?',`<p>This replaces the current design for ${getMission(state.missionId).name}. Completed flights in your archive are kept.</p>`,button('Restore starter','confirm-reset','reset')+button('Keep editing','close-modal','close','','secondary'));return;}
  if(a==='confirm-reset'){state.design=normalizeDesign(null,state.missionId);$('#modal').close();render();toast('Starter configuration restored.');return;}
  if(a==='launch'){if(state.flight&&!state.flight.complete){modal('A flight is already in progress.',`<p>Resume your current flight or replace it with this new spacecraft. The unfinished flight will not be archived.</p>`,button('Resume flight','resume','arrow')+button('Start new flight','confirm-launch','rocket','','secondary'));return;}startFlight();return;}
  if(a==='confirm-launch'){$('#modal').close();startFlight();return;}
  if(a==='resume'){$('#modal').close();navigate('flight');return;}
  if(a==='flight-command'){if(!state.flight||state.flight.complete)return;state.flight=advanceFlight(state.flight,target.dataset.id);sound();if(state.flight.complete){state.archive.unshift({name:state.flight.name||state.name,date:new Date().toISOString(),flight:state.flight});state.archive=state.archive.slice(0,12);navigate('flight');}else{render();$('.command-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});$('.command-card')?.focus({preventScroll:true});}return;}
  if(a==='abort'){modal('End this flight?',`<p>You’ll return to the spacecraft lab. This unfinished flight will be discarded; completed flights stay in the archive.</p>`,button('End flight','confirm-abort','close')+button('Keep flying','close-modal','arrow','','secondary'));return;}
  if(a==='confirm-abort'){state.flight=null;$('#modal').close();navigate('builder');return;}
  if(a==='refine'){const f=currentFlight();state.design={...f.design,payload:[...f.design.payload]};state.missionId=f.missionId;state.mode=f.mode;state.name=f.name||state.name;navigate('builder');return;}
  if(a==='open-archive'){const entry=state.archive[Number(target.dataset.index)];if(entry){reviewIndex=Number(target.dataset.index);state.view='flight';render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}return;}
  if(a==='export-report'){downloadReport();return;}
  if(a==='export-design'){download('hail-mary-spacecraft.json',JSON.stringify({v:1,missionId:state.missionId,mode:state.mode,name:state.name,design:state.design},null,2));toast('Spacecraft design downloaded.');return;}
  if(a==='share'){await shareDesign();return;}
  if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;try{if(file.size>20000)throw new Error('Design files must be smaller than 20 KB.');applyImport(JSON.parse(await file.text()));}catch(err){toast(`Could not import: ${err.message}`);}});input.click();return;}
});
function startFlight(){try{state.flight=createFlight(state.design,state.missionId,state.mode);state.flight.name=state.name;navigate('flight');sound();toast('Spacecraft in Earth orbit. You have the controls.');}catch(err){toast(err.message);}}
document.addEventListener('input',e=>{if(e.target.id==='fuel-range'){const n=$('#fuel-number');if(n)n.value=e.target.value;}});
document.addEventListener('change',e=>{const field=e.target.dataset.field;if(field==='name'){state.name=e.target.value.trim().slice(0,40)||'Hail Mary I';e.target.value=state.name;save();}if(field==='fuel'){const n=Number(e.target.value);if(!Number.isFinite(n)){toast('Enter a valid propellant mass.');render();return;}state.design=normalizeDesign({...state.design,fuel:n},state.missionId);const id=e.target.id;render();document.getElementById(id)?.focus({preventScroll:true});}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
try{if(location.hash.startsWith('#design=')){const raw=location.hash.slice(8);if(raw.length>20000)throw new Error('Link too large');applyImport(JSON.parse(decodeURIComponent(raw)));history.replaceState(null,'',location.pathname+location.search);}}catch{toast('This design link could not be loaded. A starter spacecraft is ready.');}
render();
